import { chromium } from "@playwright/test";
const id = process.argv[2];
const out = ".qa/shots/228";
const browser = await chromium.launch();
const errors = [];
for (const [name, scheme, viewport] of [["light", "light", { width: 1280, height: 900 }], ["dark", "dark", { width: 1280, height: 900 }], ["mobile", "light", { width: 390, height: 844 }]]) {
  const ctx = await browser.newContext({ storageState: "e2e/.auth.json", colorScheme: scheme, viewport });
  const page = await ctx.newPage();
  page.on("console", m => { if (m.type() === "error") errors.push(`${name} console: ${m.text()}`); });
  page.on("requestfailed", r => errors.push(`${name} failed: ${r.url()}`));
  await page.goto(`http://localhost:3100/ai?conversation=${id}`, { waitUntil: "networkidle", timeout: 90000 });
  const reply = page.locator("main").getByText("Groceries: 320");
  await reply.first().waitFor({ timeout: 30000 });
  await page.waitForTimeout(500);
  await page.getByRole("button", { name: "Copy message" }).last().scrollIntoViewIfNeeded();
  await page.screenshot({ path: `${out}/${name}.png`, fullPage: false });
  const row = page.getByRole("button", { name: "Copy message" }).last().locator("xpath=..");
  await row.screenshot({ path: `${out}/${name}-actions.png` });
  console.log(name, "actions:", await row.innerText());
  await ctx.close();
}
await browser.close();
console.log(errors.length ? errors.join("\n") : "no console errors or failed requests");
EOF
